from collections import Counter

def transform(grid):
    # Draw straight horizontal and vertical bridges between marker cells.
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    h, w = len(grid), len(grid[0])
    out = [list(row) for row in grid]
    for r, row in enumerate(grid):
        marks = [c for c, value in enumerate(row) if value != background]
        if len(marks) >= 2:
            for c in range(marks[0] + 1, marks[-1]):
                if row[c] == background:
                    out[r][c] = 3
    for c in range(w):
        marks = [r for r in range(h) if grid[r][c] != background]
        if len(marks) >= 2:
            for r in range(marks[0] + 1, marks[-1]):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out
